<template><div class="app-container"><el-button type="primary" @click="openAdd">新增模型</el-button><el-table v-loading="loading" :data="rows" class="mt16"><el-table-column prop="configName" label="配置名称"/><el-table-column prop="provider" label="供应商"/><el-table-column prop="modelName" label="模型"/><el-table-column prop="taskTypes" label="支持任务"/><el-table-column prop="enabled" label="状态"><template #default="s"><el-tag :type="s.row.enabled ? 'success' : 'info'">{{ s.row.enabled ? '启用' : '停用' }}</el-tag></template></el-table-column></el-table><el-dialog v-model="visible" title="大模型配置"><el-form :model="form" label-width="90px"><el-form-item label="名称"><el-input v-model="form.configName"/></el-form-item><el-form-item label="供应商"><el-input v-model="form.provider"/></el-form-item><el-form-item label="模型"><el-input v-model="form.modelName"/></el-form-item><el-form-item label="Endpoint"><el-input v-model="form.endpoint"/></el-form-item><el-form-item label="API Key"><el-input v-model="form.apiKey" type="password" show-password/></el-form-item><el-form-item label="任务类型"><el-input v-model="form.taskTypes" placeholder="text-image,text-video"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup name="VizoraModel">
import { listModels, addModel } from '@/api/vizora/operation'
const rows=ref([]), loading=ref(false), visible=ref(false), form=reactive({configName:'',provider:'',modelName:'',endpoint:'',apiKey:'',taskTypes:'',enabled:1,sortOrder:0})
async function load(){loading.value=true;try{const r=await listModels();rows.value=r.rows||[]}finally{loading.value=false}} function openAdd(){Object.assign(form,{configName:'',provider:'',modelName:'',endpoint:'',apiKey:'',taskTypes:'',enabled:1,sortOrder:0});visible.value=true} async function save(){await addModel(form);visible.value=false;load()} load()
</script>
